package main

import (
	"bytes"
	"log/slog"
	"strings"
	"testing"
	"time"
)

// TestRelayEnv covers the client-relayed-fetch composition-root knobs (task
// 4.3): MELLIFERA_RELAY_LEASE (the claim handout — feeds Relay.LeaseTTL)
// and MELLIFERA_RELAY_MAX_BODY (the result body cap — feeds
// api.Deps.RelayMaxBody). For both: unset/empty → the default; a set value →
// verbatim; a malformed value → the default + a logged warning naming the knob
// (envDuration's / envInt's INV-env-defaults contract). The lease accepts only
// time.ParseDuration values — a bare seconds integer is malformed, the unit is
// part of the value. Empty reads as unset because envDuration/envInt collapse
// the two — os.Getenv cannot distinguish them (the TestEnvInt precedent).
func TestRelayEnv(t *testing.T) {
	t.Run("lease", func(t *testing.T) {
		const key = "MELLIFERA_RELAY_LEASE"
		for _, tc := range []struct {
			name     string
			val      string
			want     time.Duration
			wantWarn bool
		}{
			{"unset_uses_default", "", 2 * time.Minute, false},
			{"set_serves_verbatim", "90s", 90 * time.Second, false},
			{"set_minutes_serve_verbatim", "5m", 5 * time.Minute, false},
			{"malformed_falls_back_with_warning", "soon", 2 * time.Minute, true},
			{"bare_seconds_int_is_malformed", "120", 2 * time.Minute, true},
		} {
			t.Run(tc.name, func(t *testing.T) {
				t.Setenv(key, tc.val)
				var buf bytes.Buffer
				if tc.wantWarn {
					prev := slog.Default()
					slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
					t.Cleanup(func() { slog.SetDefault(prev) })
				}
				if got := relayLease(); got != tc.want {
					t.Errorf("relayLease() with %s=%q = %v, want %v", key, tc.val, got, tc.want)
				}
				if tc.wantWarn && !strings.Contains(buf.String(), key) {
					t.Errorf("malformed %s logged no warning naming the knob; output: %q", key, buf.String())
				}
			})
		}
	})
	t.Run("max_body", func(t *testing.T) {
		const key = "MELLIFERA_RELAY_MAX_BODY"
		for _, tc := range []struct {
			name     string
			val      string
			want     int64
			wantWarn bool
		}{
			{"unset_uses_default", "", 2 * 1024 * 1024, false},
			{"set_serves_verbatim", "1048576", 1 * 1024 * 1024, false},
			{"malformed_falls_back_with_warning", "big", 2 * 1024 * 1024, true},
			{"negative_passes_through_unclamped", "-1", -1, false},
		} {
			t.Run(tc.name, func(t *testing.T) {
				t.Setenv(key, tc.val)
				var buf bytes.Buffer
				if tc.wantWarn {
					prev := slog.Default()
					slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
					t.Cleanup(func() { slog.SetDefault(prev) })
				}
				if got := relayMaxBody(); got != tc.want {
					t.Errorf("relayMaxBody() with %s=%q = %d, want %d", key, tc.val, got, tc.want)
				}
				if tc.wantWarn && !strings.Contains(buf.String(), key) {
					t.Errorf("malformed %s logged no warning naming the knob; output: %q", key, buf.String())
				}
			})
		}
	})
}
